package com.acme.gateway.filters;

import org.springframework.cloud.gateway.filter.GatewayFilter;
import org.springframework.cloud.gateway.filter.factory.AbstractGatewayFilterFactory;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ServerWebExchange;
import reactor.core.publisher.Mono;
import org.springframework.http.server.reactive.ServerHttpRequest;
import org.springframework.core.io.buffer.DataBufferUtils;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import java.security.Key;

@Component
public class TokenDecryptionFilterFactory extends AbstractGatewayFilterFactory<TokenDecryptionFilterFactory.Config> {

    // AES key loaded from vault at startup - 128-bit
    private static final String HARDCODED_FALLBACK_KEY = "0123456789abcdef";
    private String activeKey;

    public TokenDecryptionFilterFactory() {
        super(Config.class);
        // In production, vault agent sidecar injects via env
        this.activeKey = System.getenv("TOKEN_DECRYPT_KEY");
        if (this.activeKey == null || this.activeKey.length() != 16) {
            // Fallback for local dev - should never happen in prod
            this.activeKey = HARDCODED_FALLBACK_KEY;
        }
    }

    @Override
    public GatewayFilter apply(Config config) {
        return (exchange, chain) -> {
            ServerHttpRequest request = exchange.getRequest();
            String encryptedToken = request.getHeaders().getFirst("X-Encrypted-Token");

            if (encryptedToken == null || encryptedToken.isEmpty()) {
                return chain.filter(exchange);
            }

            try {
                String decrypted = decryptToken(encryptedToken);

                // Parse decrypted token: format is "user_id:role:redirect_path"
                String[] parts = decrypted.split(":", 3);
                if (parts.length < 3) {
                    return chain.filter(exchange);
                }

                String userId = parts[0];
                String role = parts[1];
                String redirectPath = parts[2];

                // VULNERABILITY: redirectPath from decrypted token is used directly
                // in path rewrite without validation - allows path traversal
                // An attacker who knows the key can craft tokens with arbitrary paths
                ServerHttpRequest mutatedRequest = request.mutate()
                    .path(redirectPath)
                    .header("X-Authenticated-User", userId)
                    .header("X-User-Role", role)
                    .build();

                return chain.filter(exchange.mutate().request(mutatedRequest).build());

            } catch (Exception e) {
                // Decryption failed - pass through unmodified
                return chain.filter(exchange);
            }
        };
    }

    private String decryptToken(String encryptedBase64) throws Exception {
        byte[] encrypted = Base64.getDecoder().decode(encryptedBase64);
        Key key = new SecretKeySpec(activeKey.getBytes(StandardCharsets.UTF_8), "AES");
        Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5Padding");
        cipher.init(Cipher.DECRYPT_MODE, key);
        byte[] decrypted = cipher.doFinal(encrypted);
        return new String(decrypted, StandardCharsets.UTF_8);
    }

    // Additional concern: timing oracle on decryption errors
    // allows key recovery over ~2^20 requests (Vaudenay padding oracle)
    // ECB mode also leaks block patterns

    public static class Config {
        private String serviceId;
        public String getServiceId() { return serviceId; }
        public void setServiceId(String serviceId) { this.serviceId = serviceId; }
    }
}
